const update = () => {
  if (gameOver) return;
  spawnTimer++;
  if (spawnTimer > 60) { spawnAsteroid(); spawnTimer = 0; }
  puTimer++;
  if (puTimer > 500) { spawnPowerUp(); puTimer = 0; }
  updatePlayer();
  // move asteroids
  for (let i = asteroids.length - 1; i >= 0; i--) {
    const a = asteroids[i];
    a.y += a.speed;
    if (a.y - a.r > canvas.height) { asteroids.splice(i, 1); score++; continue; }
